const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedIds)) {
  staticData.processedIds = [];
}

const item = items[0].json;
const idMessage = String(item.idMessage || '').trim();
const chatId = String(item.chatId || '').trim();
const mensaje = String(item.mensaje || '').trim();

// Sin texto o sin chat: no responder
if (!chatId || !mensaje) {
  return [];
}

// Deduplicar por idMessage (reintentos / ecos)
if (idMessage) {
  if (staticData.processedIds.includes(idMessage)) {
    return [];
  }
  staticData.processedIds.push(idMessage);
  if (staticData.processedIds.length > 300) {
    staticData.processedIds = staticData.processedIds.slice(-300);
  }
}

return [{
  json: {
    chatId,
    mensaje,
    nombre: item.nombre || '',
    idMessage,
    sender: item.sender || '',
  },
}];

const raw = String($json.output || $json.text || '').trim();
const chatId = $('Normalizar campos').item.json.chatId;

let message = raw;
let pedidoJson = null;

// Si el agente devolvió JSON (o texto + JSON), no mandarlo al cliente
const jsonMatch = raw.match(/\{[\s\S]*"estado"[\s\S]*\}/);
if (jsonMatch) {
  pedidoJson = jsonMatch[0];
  const before = raw.slice(0, jsonMatch.index).trim();
  message = before || '¡Listo! Pedido confirmado. En breve te contactamos para cerrar detalles. ✅';
}

// Evitar mensajes vacíos
if (!message) {
  message = '¿En qué te puedo ayudar?';
}

// Limitar tamaño extremo
if (message.length > 1200) {
  message = message.slice(0, 1200) + '…';
}

return [{
  json: {
    chatId,
    message,
    pedidoJson,
  },
}];
